"N-й век": "N-asr",
"N-й век — годы с N по N, N-й — с N по N и так далее. Год N — это N-й век.": "N-asr — N dan N gacha bo‘lgan yillar, N-asr — N dan N gacha va hokazo. N-yil N-asrga kiradi.",
"N/N от N = ?": "N/N dan N = ?",
"N/N числа равна N. Найди всё число.": "Sonning N/N qismi N ga teng. Butun sonni top.",
"N:N + N мин = N:N": "N:N + N daq = N:N",
"N:N + N мин. До N:N ещё N мин; потом ещё N мин. Получается N:N.": "N:N + N daq. N:N ga yetish uchun yana N daq kerak; keyin yana N daq. N:N hosil bo‘ladi.",
"N:N + N мин: часы те же, минуты N + N = N. Получается N:N.": "N:N + N daq: soatlar o‘zgarmaydi, daqiqalar N + N = N. N:N hosil bo‘ladi.",
"N:N − N мин = N:N": "N:N − N daq = N:N",
"N:N − N:N = N мин.": "N:N − N:N = N daq.",
"x : N − N = N. Уменьшаемое x : N = N + N = N, значит x = N · N = N.": "x : N − N = N. Kamayuvchi x : N = N + N = N, demak x = N · N = N.",
"x больше N": "x N dan katta",
"x меньше N": "x N dan kichik",
"{N, N} — подмножество {N, N, N, N}.": "{N, N} — {N, N, N, N} ning qism to‘plami.",
"{N, N} — это ... множества {N, N, N, N}": "{N, N} — {N, N, N, N} to‘plamning ...",
"«N + N = N» — ложное высказывание.": "«N + N = N» — noto‘g‘ri tasdiq.",
"«N − N = N» — истинное высказывание: оно верно. «Алматы — столица Казахстана» — ложное, столица — Астана.": "«N − N = N» — to‘g‘ri tasdiq: bu to‘g‘ri. «Almaty — Qozog‘iston poytaxti» noto‘g‘ri, poytaxt — Astana.",
