"Точки стоят на одной высоте. Считаем клетки: N минус N будет N.": "Nuqtalar bir xil balandlikda. Kataklarni sanaymiz: N minus N teng N.",
"Ты купил N ручек по N тенге и заплатил N тенге. Сколько сдачи?": "Sen N ta ruchkani N tengedan sotib olding va N tenge to‘lading. Qaytim qancha?",
"Ты купил N ручки по N тенге и заплатил N тенге. Сколько сдачи?": "Sen N ta ruchkani N tengedan sotib olding va N tenge to‘lading. Qaytim qancha?",
"У Али N карточек, у Данияра на N меньше. Сколько у Данияра? N − N = N. А вместе: N + N = N.": "Alida N ta karta bor, Daniyarda N ta kam. Daniyarda nechta bor? N − N = N. Va birgalikda: N + N = N.",
"У Али N марок, а у Айи на N марок больше. Сколько марок у Айи?": "Alida N ta marka bor, Ayada esa N ta ko‘p marka bor. Ayada nechta marka bor?",
