"У Алии N наклеек, у Тимура на N меньше. Сколько наклеек у Тимура?": "Aliyada N ta stiker bor, Timurda N ta kam. Timurda nechta stiker bor?",
"У Алмаса N рубашки и N пары шорт. Сколько разных нарядов можно составить?": "Almasda N ta ko‘ylak va N ta shortik bor. Necha xil kiyim to‘plami tuzish mumkin?",
"У Данияра N марки, а у Ерлана — в N раз больше. Сколько марок у Ерлана?": "Daniyarda N ta marka bor, Yerlanda N marta ko‘p. Yerlanda nechta marka bor?",
"У Данияра N марки, а у Ерлана — в N раза больше. Сколько марок у Ерлана?": "Daniyarda N ta marka bor, Yerlanda N marta ko‘p. Yerlanda nechta marka bor?",
"У Данияра N марок, а у Ерлана — в N раз больше. Сколько марок у Ерлана?": "Daniyarda N ta marka bor, Yerlanda N marta ko‘p. Yerlanda nechta marka bor?",
"У Данияра N марок, а у Ерлана — в N раза больше. Сколько марок у Ерлана?": "Daniyarda N ta marka bor, Yerlanda N marta ko‘p. Yerlanda nechta marka bor?",
