"У какого столбика значение самое маленькое?": "Qaysi ustunning qiymati eng kichik?",
"У квадрата все стороны равны: N · N = N см": "Kvadratning barcha tomonlari teng: N · N = N sm",
"У квадрата со стороной N см площадь N² = N см². Квадрат числа — это площадь квадрата.": "Tomoni N sm bo‘lgan kvadratning yuzi N² = N sm². Sonning kvadrati — kvadratning yuzi.",
"У квадрата четыре равные стороны. N умножить на четыре будет N сантиметров.": "Kvadratning to‘rtta tomoni teng. N ni to‘rtga ko‘paytirsak N santimetr bo‘ladi.",
"У квадрата четыре равные стороны: N · N = N": "Kvadratning to‘rtta tomoni teng: N · N = N",
"У куба N вершин.": "Kubning N ta uchi bor.",
"У куба N граней: все они — равные квадраты.": "Kubning N ta yog‘i bor: ularning hammasi teng kvadratlar.",
"У куба N рёбер.": "Kubning N ta qirrasi bor.",
"У куба восемь вершин.": "Kubning sakkizta uchi bor.",
"У куба двенадцать рёбер.": "Kubning o‘n ikkita qirrasi bor.",
"У куба с ребром N см объём N³ = N см³. Куб числа — число кубиков, из которых собран большой куб.": "Qirrasi N sm bo‘lgan kubning hajmi N³ = N sm³. Sonning kubi — katta kubni tashkil qiladigan kichik kublar soni.",
"У куба шесть граней. Все они равные квадраты.": "Kubning oltita yog‘i bor. Ularning hammasi teng kvadratlar.",
"У тебя N тенге. Хватит ли денег на покупки за N и N тенге?": "Senda N tenge bor. N va N tengelik xaridlarga pul yetadimi?",
