"Умножаем N на N и прибавляем остаток N. Получается N.": "N ni N ga ko‘paytiramiz va N qoldiqni qo‘shamiz. N hosil bo‘ladi.",
"Умножаем на N, затем на N: N · N = N, N · N = N.": "N ga, keyin N ga ko‘paytiramiz: N · N = N, N · N = N.",
"Умножаем на круглое": "Yaxlit songa ko‘paytirish",
"Умножаем на однозначное": "Bir xonali songa ko‘paytirish",
"Умножать двузначные и круглые числа на однозначные и круглые приёмами": "Ikki xonali va yaxlit sonlarni bir xonali va yaxlit sonlarga usullar yordamida ko‘paytirish",
"Умножать двузначные и трёхзначные числа на однозначное в столбик": "Ikki va uch xonali sonlarni bir xonali songa ustunli ko‘paytirish",
"Умножение и деление на N и N": "N va N ga ko‘paytirish va bo‘lish",
"Уравнение сложной структуры содержит неизвестное в составном выражении, например N · x + N = N. Сначала находим значение выражения с неизвестным: N · x = N − N = N, затем неизвестный множитель: x = N : N = N. Проверка: N · N + N = N. Верно. Порядок: сначала определяем, какое действие выполняется последним.": "Murakkab tuzilishli tenglamada noma’lum murakkab ifoda ichida bo‘ladi, masalan N · x + N = N. Avval noma’lumli ifodaning qiymatini topamiz: N · x = N − N = N, keyin noma’lum ko‘paytuvchini: x = N : N = N. Tekshirish: N · N + N = N. To‘g‘ri. Tartib: avval qaysi amal oxirgi bajarilishini aniqlaymiz.",
"Уравнения сложной структуры": "Murakkab tuzilishli tenglamalar",
"Урок начался в N часов N минут и закончился в N часов N минут. Сколько минут шёл урок?": "Dars N soat N daqiqada boshlandi va N soat N daqiqada tugadi. Dars necha daqiqa davom etdi?",
"Урок начался в N часов N минут и закончился в N часов. Сколько минут шёл урок?": "Dars N soat N daqiqada boshlandi va N soatda tugadi. Dars necha daqiqa davom etdi?",
"Урок начался в N часов и закончился в N часов N минут. Сколько минут шёл урок?": "Dars N soatda boshlandi va N soat N daqiqada tugadi. Dars necha daqiqa davom etdi?",
"Урок начался в N:N и закончился в N:N. Сколько минут длился урок?": "Dars N:N da boshlandi va N:N da tugadi. Dars necha daqiqa davom etdi?",
"Урок начался в N:N и закончился в N:N. Сколько минут шёл урок?": "Dars N:N da boshlandi va N:N da tugadi. Dars necha daqiqa davom etdi?",
"Фигура разделена на N равных частей — это знаменатель. Закрашено N — это числитель. Закрашено N/N.": "Shakl N ta teng qismga bo‘lingan — bu maxraj. N tasi bo‘yalgan — bu surat. N/N bo‘yalgan.",
"Футболки: красная, синяя. Шорты: белые, чёрные, серые. Вариантов N · N = N.": "Futbolkalar: qizil, ko‘k. Shortiklar: oq, qora, kulrang. Variantlar: N · N = N.",
